{
  "probability": 0.01,
  "range_low": 0.01,
  "range_high": 0.04,
  "summary": [
    "Current forecasts place CDU as the leading party in Baden-Württemberg, with AfD polling around high-teens to 20% and Greens close behind.",
    "Historical base-rate constraints indicate AfD has never led BW in seat tallies, anchoring expectations toward CDU/Greens instead.",
    "Even with occasional signs of AfD catching up in some polls, the consolidated evidence keeps AfD’s odds of winning the most seats extremely low.",
    "Undecided voters and late-campaign shifts could modestly adjust margins but are unlikely to overturn the current consensus."
  ],
  "confidence": "high",
  "narrative": "Anchored to the historical pattern that AfD has not led BW and to multiple late-February polls showing CDU ahead with AfD around 18–20%, the posterior probability that AfD wins the most seats remains near-zero. Calibrated updates from both downward pressure (historical base-rate, CDU lead) and modest upward risks (late swing, undecided turnout) yield a compact, highly uncertain but still very small probability band around 1%.",
  "justification": {
    "anchor": {
      "probability": 0.05,
      "basis": "Historical Baden-Württemberg: AfD has never led BW; anchor probability for AfD being the largest party is very low."
    },
    "factor_updates": [
      {
        "factor": "CDU polling lead",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Late-February polls consistently show CDU around 27–29%, Greens around 21–25%, AfD around 18–20%, making AfD the unlikely largest party."
      },
      {
        "factor": "Historical baseline",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Historical elections indicate AfD has not led BW; this low prior probability anchors expectations away from AfD largest."
      },
      {
        "factor": "AfD overtaking Greens in some polls",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Some polls show AfD near or above Greens; could modestly raise odds if trends persist, but not enough to overturn CDU lead in current consensus."
      },
      {
        "factor": "Undecided voters near election day",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "A notable share of undecided voters could shift late, providing limited upside for AfD but insufficient to become largest."
      },
      {
        "factor": "Late campaign surges / turnout dynamics",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Low-probability tail-risk that a late swing could boost AfD, yet current data suggest this would still not overcome CDU lead."
      }
    ],
    "synthesis_rationale": "Starting from the strong anchor in the reference class, the dominant updates push probability toward near-zero due to CDU lead and historical precedent. While several upward risks exist, they are not calibrated to overcome the current plurality; the final posterior is set at 1% with a 1–4% uncertainty band to reflect residual variance and late-stage volatility."
  }
}

